  const annotated = execFileSync('git', ['grep', '-c', '@legacy-tolerance', '--', 'engine', 'packs'], { cwd: root, encoding: 'utf8' });
  assert.ok(annotated.split('\n').filter(Boolean).length > 5, 'the real tree carries annotated tolerances to judge');
});
